const inputJson = $input.item.json || {};
const body = inputJson.body || inputJson;
const issue = body.issue || inputJson.issue || {};
const issueId = issue.id || body.issue_id || inputJson.issue_id || "";
const images = issue.images || body.images || [];
const mapsUrl = issue.maps_link || (issue.lat && issue.lng ? `https://www.google.com/maps?q=${issue.lat},${issue.lng}` : "https://maps.google.com");

const formattedPriority = typeof issue.priority_score === 'number' ? (issue.priority_score >= 1 ? Math.round(issue.priority_score) : issue.priority_score.toFixed(2)) : (issue.priority_score || '0');

let formattedMessage = "🚨 *CIVICFIX MUNICIPAL DISPATCH*\n\n" +
  "📌 *Issue*: " + (issue.title || "Infrastructure Defect") + "\n" +
  "📄 *Description*: " + (issue.description || "No detailed description provided.") + "\n" +
  "📍 *Location*: " + (issue.address || "Addis Ababa") + "\n" +
  "🏙️ *Sub-City*: " + (issue.subcity || "Bole") + "\n" +
  "👷 *Assigned Unit*: " + (issue.assigned_unit || "Field Unit 1") + "\n" +
  "⚡ *Priority Score*: " + formattedPriority + "\n" +
  "📝 *Officer Notes*: " + (body.dispatch_notes || "Immediate priority repair requested.") + "\n\n";

if (images && images.length > 0) {
  formattedMessage += "🖼️ [View Attached Issue Photo](" + images[0] + ")\n\n";
}

formattedMessage += "👇 *Use the interactive buttons below on your phone:*";

const inlineKeyboard = [
  [
    { "text": "🗺️ Open Navigation", "url": mapsUrl }
  ],
  [
    { "text": "📸 Submit Repair Proof", "callback_data": `resolve:${issueId}` },
    { "text": "💵 Log Cost (4500 ETB)", "callback_data": `cost:${issueId}` }
  ],
  [
    { "text": "🌐 አማርኛ / English", "callback_data": `lang:${issueId}` }
  ]
];

return {
  json: {
    issue_id: issueId,
    subcity: issue.subcity || "Bole",
    assigned_unit: issue.assigned_unit || "Field Unit 1",
    formatted_message: formattedMessage,
    inline_keyboard: inlineKeyboard,
    maps_link: mapsUrl,
    raw_payload: body
  }
};
